export const PluginLogo: Component<{ plugin: PluginDef; size?: number }> = (props) => (
  <span
    class="flex shrink-0 items-center justify-center rounded-[10px] border border-[rgba(178,140,255,0.14)] bg-white/[0.055]"
    style={{ width: `${props.size ?? 34}px`, height: `${props.size ?? 34}px` }}
    aria-hidden="true"
  >
    <svg viewBox="0 0 24 24" style={{ width: "58%", height: "58%" }}>
      <path d={brandPaths[props.plugin.logo]} fill={props.plugin.fill} />
    </svg>
  </span>
)
